def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)

    def uniform_lines(horizontal):
        n = h if horizontal else w
        m = w if horizontal else h
        lines = []
        for i in range(n):
            line = [grid[i][j] if horizontal else grid[j][i] for j in range(m)]
            if len(set(line)) == 1 and line[0] != bg:
                lines.append((i, line[0]))
        return lines

    # A repeated uniform separator defines the tile spacing. With a single
    # separator, its tile is the region on either side of that line.
    for horizontal in (True, False):
        lines = uniform_lines(horizontal)
        if not lines:
            continue
        n = h if horizontal else w
        if len(lines) >= 2:
            gaps = [lines[i + 1][0] - lines[i][0] for i in range(len(lines) - 1)]
            period = min(gaps)
        else:
            sep = lines[0][0]
            period = max(sep, n - sep - 1)
            if period == 0:
                continue

        out = [row[:] for row in grid]
        for r in range(h):
            for c in range(w):
                pos = r if horizontal else c
                # Preserve separator cells; propagate all other foreground marks.
                if grid[r][c] == bg or any(pos == i for i, _ in lines):
                    continue
                target = pos % period
                if horizontal:
                    for rr in range(target, h, period):
                        if not any(rr == i for i, _ in lines):
                            out[rr][c] = grid[r][c]
                else:
                    for cc in range(target, w, period):
                        if not any(cc == i for i, _ in lines):
                            out[r][cc] = grid[r][c]
        return out

    return [row[:] for row in grid]
