def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # A solid non-background row marks the end of a repeating tile.
    marker = next(
        ((r, row[0]) for r, row in enumerate(grid)
         if len(set(row)) == 1 and row[0] != background),
        None
    )
    if marker is None:
        return [row[:] for row in grid]

    marker_row, marker_color = marker
    period = marker_row + 1
    out = [[background] * w for _ in range(h)]

    # Copy the separator into each tile, and repeat all other colored cells
    # according to their position within the tile.
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value == background:
                continue
            if r % period == period - 1:
                out[r][c] = marker_color
            else:
                for rr in range(r % period, h, period):
                    if rr % period != period - 1:
                        out[rr][c] = value
    return out
